PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : CONST INT := 10;
    HighLimit : CONST INT := 90;
END_VAR

IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

