PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    A_not_open : BOOL;
    B_not_open : BOOL;
END_VAR

A_not_open := NOT DoorA;
B_not_open := NOT DoorB;

CASE 
    WHEN OpenA_Cmd AND A_not_open AND OpenB_Cmd AND B_not_open THEN
        DoorA := TRUE;
        DoorB := FALSE;
    WHEN OpenA_Cmd AND A_not_open THEN
        DoorA := TRUE;
        DoorB := FALSE;
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
END_CASE;
END_PROGRAM

