    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL;
END_VAR

// Initialize conveyor to off
Conveyor := FALSE;

// Check for start conditions
IF StartPB AND GuardClosed AND NOT Fault THEN
    // Start the conveyor if all conditions are met
    Conveyor := TRUE;
    Running := TRUE;
ELSIF StopPB OR NOT GuardClosed OR Fault THEN
    // Stop the conveyor if any stop condition is met
    Conveyor := FALSE;
    Running := FALSE;
END_IF;

END_PROGRAM

