GuardTimer(IN := NOT GuardClosed, PT := T#5s);

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
ELSIF StartPB AND GuardClosed AND NOT Fault AND NOT Running THEN
    Running := TRUE;
END_IF;

Conveyor := Running;

// Reset guard timer if safe
IF GuardClosed AND NOT Fault THEN
    GuardTimer(IN := TRUE, PT := T#5s);
END_IF;

END_PROGRAM

