        NS_green(IN := FALSE);
        NS_yellow(IN := TRUE, PT := T#1s);
        NS_allred(IN := FALSE);
        EW_green(IN := FALSE);
        EW_yellow(IN := FALSE);
        EW_allred(IN := TRUE);

        IF NS_yellow.Q THEN
            State := 0;
        ELSIF NS_allred.Q THEN
            State := 2;
        END_IF;

    2:
        NS_green(IN := FALSE);
        NS_yellow(IN := FALSE);
        NS_allred(IN := TRUE, PT := T#1s);
        EW_green(IN := FALSE);
        EW_yellow(IN := FALSE);
        EW_allred(IN := FALSE);

        IF NS_allred.Q THEN
            State := 3;
        END_IF;

    3:
        NS_green(IN := FALSE);
        NS_yellow(IN := FALSE);
        NS_allred(IN := FALSE);
        EW_green(IN := TRUE, PT := T#2s);
        EW_yellow(IN := FALSE);
        EW_allred(IN := FALSE);

        IF EW_green.Q THEN
            State := 4;
        ELSIF EW_allred.Q THEN
            State := 5;
        END_IF;

    4:
        NS_green(IN := FALSE);
        NS_yellow(IN := FALSE);
        NS_allred(IN := FALSE);
        EW_green(IN := FALSE);
        EW_yellow(IN := TRUE, PT := T#1s);
        EW_allred(IN := FALSE);

        IF EW_yellow.Q THEN
            State := 3;
        ELSIF EW_allred.Q THEN
            State := 5;
        END_IF;

