        NS_yellow(IN := FALSE);
        NS_allred(IN := FALSE);
        EW_green(IN := FALSE);
        EW_yellow(IN := FALSE);
        EW_allred(IN := TRUE, PT := T#1s);

        IF EW_allred.Q THEN
            State := 0;
        END_IF;
