NS_Y := NS_yellow.Q AND NOT EW_green.Q;
NS_R := NS_allred.Q OR EW_green.Q;

EW_G := EW_green.Q AND NOT NS_green.Q;
EW_Y := EW_yellow.Q AND NOT NS_green.Q;
EW_R := EW_allred.Q OR NS_green.Q;

END_PROGRAM

