PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILL : INT := 1;
    HEAT : INT := 2;
    REACT : INT := 3;
    DRAIN : INT := 4;
END_VAR

CASE State OF
    IDLE:
        IF StartBatch AND EStop THEN
            State := FILL;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    FILL:
        IF NOT EStop AND Level >= LVL_HIGH AND Level >= LIQ_MIN THEN
            State := HEAT;
        END_IF;
        IF EStop OR Level < LIQ_MIN THEN
            State := IDLE;
        END_IF;
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    HEAT:
        IF NOT EStop AND Level >= LIQ_MIN AND Temp >= TEMP_SET THEN
            State := REACT;
        END_IF;
        IF EStop OR Level < LIQ_MIN THEN
            State := IDLE;
        END_IF;
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

    REACT:
        IF NOT EStop AND Level >= LIQ_MIN AND Temp >= TEMP_SET AND TON_1.Q THEN
            State := DRAIN;
        END_IF;
        IF EStop OR Level < LIQ_MIN THEN
            State := IDLE;
        END_IF;
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        TON_1(IN := TRUE, PT := PT_REACT);

    DRAIN:
        IF NOT EStop AND Level <= LVL_LOW AND Level >= LIQ_MIN THEN
            State := IDLE;
        END_IF;
        IF EStop OR Level < LIQ_MIN THEN
            State := IDLE;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE

// Ensure fill and drain valves never open together
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND EStop AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: // Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH AND EStop THEN
            State := 2;
        END_IF;
    2: // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET AND EStop THEN
            State := 3;
        END_IF;
    3: // React
        Heater := TRUE;
        Agitator := TRUE;
        T1(IN := TRUE, PT := PT_REACT);
        IF T1.Q OR NOT EStop THEN
            State := 4;
        END_IF;
    4: // Drain
        FillValve := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW AND EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
FillValve AND DrainValve => ERROR;
NOT EStop => Error;
Level < LIQ_MIN AND (Heater OR Agitator) => ERROR;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
