            END_IF;
        FILL :
            IF Level >= LVL_HIGH THEN
                State := HEAT;
            END_IF;
            FillValve := TRUE;
        HEAT :
            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := REACT;
            END_IF;
            Heater := TRUE;
            Agitator := TRUE;
        REACT :
            IF T#3s <= PT_REACT THEN
                State := DRAIN;
            END_IF;
            Heater := TRUE;
            Agitator := TRUE;
        DRAIN :
            IF Level <= LVL_LOW THEN
                State := IDLE;
            END_IF;
            DrainValve := TRUE;
    END_CASE;
END_IF;

END_PROGRAM

