            State := 4;
            HeatTimer(IN := TRUE, PT := T#1s);
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF DrainValve AND Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
