END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILL : INT := 1;
    HEAT : INT := 2;
    REACT : INT := 3;
    DRAIN : INT := 4;
END_VAR

IF NOT EStop THEN
    State := IDLE;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        IDLE:
            IF Level < LVL_HIGH THEN
                State := FILL;
            ELSE
                State := HEAT;
            END_IF;
        FILL:
            IF Level >= LVL_HIGH THEN
                State := HEAT;
            END_IF;
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        HEAT:
            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := REACT;
            END_IF;
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        REACT:
            IF TON_1.Q THEN
                State := DRAIN;
            END_IF;
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            TON_1(IN := TRUE, PT := PT_REACT);
        DRAIN:
            IF Level <= LVL_LOW THEN
                State := IDLE;
            END_IF;
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
    END_CASE;
END_IF;

IF FillValve AND DrainValve OR Level < LIQ_MIN THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

