PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0: -- Idle
            Pump := FALSE;
            Valve := FALSE;
            IF StartCycle AND Level < 90 THEN
                State := 1;
            END_IF;
        1: -- Filling
            Pump := TRUE;
            Valve := FALSE;
            IF Level >= 90 THEN
                State := 2;
            END_IF;
        2: -- Draining
            Pump := FALSE;
            Valve := TRUE;
            IF Level <= 10 THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

-- Safety conditions
IF Pump AND Valve THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;
IF Level >= 90 AND Pump THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;
IF Level <= 10 AND Valve THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;
END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSIF State = 0 AND StartCycle AND Level < 90 THEN
    State := 1;
    Pump := TRUE;
    Valve := FALSE;
ELSIF State = 1 AND Level >= 90 THEN
    State := 2;
    Pump := FALSE;
    Valve := TRUE;
ELSIF State = 2 AND Level <= 10 THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
State := CASE
    EStop => 0,
    ELSE =>
        CASE State OF
            0 => IF StartCycle AND Level < 90 THEN 1 ELSE 0 END_IF,
            1 => IF Level >= 90 THEN 2 ELSE 1 END_IF,
            2 => IF Level <= 10 THEN 0 ELSE 2 END_IF,
            _ => 0
